+
+export const complete = async (jobId: string): Promise<void> => {
+  await pool.query("UPDATE jobs SET status = 'completed' WHERE id = $1", [jobId]);
+};
+
+export const nack = async (jobId: string): Promise<void> => {
+  await pool.query("UPDATE jobs SET status = 'ready' WHERE id = $1", [jobId]);
+};
+
+export const getJob = async (jobId: string): Promise<Job | null> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM jobs WHERE id = $1",
+    [jobId],
+  );
+  const row = result.rows[0];
+  return row || null;
+};
