@@ -0,0 +1,55 @@
+import express from "express";
+import * as jobs from "./jobs.ts";
+
+const app = express();
+app.use(express.json());
+
+app.get("/api/jobs/next", async (req, res) => {
+  try {
+    const job = await jobs.claimNext();
+    if (job === null) {
+      return res.status(204).send();
+    }
+    res.json(job);
+  } catch (error) {
+    console.error("Error claiming job:", error);
+    res.status(500).json({ error: "Failed to claim job" });
+  }
+});
+
+app.post("/api/jobs/:jobId/complete", async (req, res) => {
+  try {
+    const { jobId } = req.params;
+    const job = await jobs.getJob(jobId);
+    if (job === null) {
+      return res.status(404).json({ error: "Job not found" });
+    }
+    await jobs.complete(jobId);
+    res.json({ status: "completed" });
+  } catch (error) {
+    console.error("Error completing job:", error);
+    res.status(500).json({ error: "Failed to complete job" });
+  }
+});
+
+app.post("/api/jobs/:jobId/nack", async (req, res) => {
+  try {
+    const { jobId } = req.params;
+    const job = await jobs.getJob(jobId);
+    if (job === null) {
+      return res.status(404).json({ error: "Job not found" });
+    }
+    await jobs.nack(jobId);
+    res.json({ status: "returned_to_queue" });
+  } catch (error) {
+    console.error("Error nacking job:", error);
+    res.status(500).json({ error: "Failed to nack job" });
+  }
+});
+
+const PORT = process.env.PORT || 3000;
+app.listen(PORT, () => {
+  console.log(`Job API server listening on port ${PORT}`);
+});
+
+export { app };
